    "description": "Haltères Bicep Curl Lunge With Bowling Motion. Fiche banque « Biceps » — équipement : Haltères. Cible principale : Biceps brachial. Muscles secondaires : Brachial, Avant-bras. Pieds ancrés, genoux dans l’axe des pointes. Buste gainé, descente contrôlée jusqu’à l’amplitude propre. Descends en gardant les talons au sol, remonte en poussant le sol, hanches et genoux synchronisés. Reste sur cette variante précise — ne la confonds pas avec un mouvement voisin de la même famille biceps. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
