    "description": "Haltères Unilatéral Ventral Curl. Fiche banque « Biceps » — équipement : Haltères. Cible principale : Biceps brachial. Muscles secondaires : Brachial, Avant-bras. Coudes près du corps, épaules basses. Charge adaptée : le buste ne doit pas donner d’élan. Travail unilatéral : termine un côté (ou alterne proprement) en gardant le bassin et les épaules de niveau — pas de rotation parasite pour aider. Fléchis jusqu’à la contraction maximale sans monter les coudes. Étire presque complètement en bas sans hyperextension brutale. Ce n’est pas un rowing ni un développé : seuls les coudes fléchissent. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
