    "equipment": "Élastique",
    "difficulty": 1,
    "isNew": true,
    "description": "Élastique Front Élévation Latérale. Fiche banque « Épaules » — équipement : Élastique. Cible principale : Deltoïdes moyens. Muscles secondaires : Trapèzes, Coiffe des rotateurs. Charges légères prioritaires. Épaules basses, pas d’élan du buste ni des trapèzes pour “voler” la série. Monte jusqu’à l’horizontale (ou un peu au-dessus si la technique reste propre), marque une courte pause, redescends sans balancier. Ce n’est pas un shrug : les trapèzes ne doivent pas avaler le mouvement. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
