    "equipment": "Haltères",
    "difficulty": 2,
    "isNew": true,
    "description": "Haltères Unilatéral Reverse Oiseau With Support. Fiche banque « Épaules » — équipement : Haltères. Cible principale : Deltoïdes. Muscles secondaires : Trapèzes, Coiffe des rotateurs. Légère flexion des coudes maintenue constante. Poitrine ouverte, trajectoire en arc contrôlé. Travail unilatéral : termine un côté (ou alterne proprement) en gardant le bassin et les épaules de niveau — pas de rotation parasite pour aider. Ouvre jusqu’à un étirement confortable de la poitrine / des deltoïdes, puis referme en contractant la cible — pas un développé déguisé. Ce n’est pas un développé : si les coudes s’étendent trop, tu perds l’écarté. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
