    "description": "Haltères Unilatéral Développé Épaules v 2. Fiche banque « Épaules » — équipement : Haltères. Cible principale : Deltoïdes antérieurs. Muscles secondaires : Trapèzes, Coiffe des rotateurs. Installe-toi de façon stable avec Haltères. Omoplates calées, poignets neutres, pieds ancrés. Travail unilatéral : termine un côté (ou alterne proprement) en gardant le bassin et les épaules de niveau — pas de rotation parasite pour aider. Pousse jusqu’à l’extension presque complète sans verrouiller d’un coup, puis redescends en contrôlant 2–3 secondes. Ce n’est pas un écarté : la trajectoire reste un press, coudes sous la charge. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
