  "weighted élévation frontale": {
    "name": "Weighted Élévation Frontale",
    "category": "Épaules",
    "primaryMuscles": [
      "Deltoïdes antérieurs"
    ],
    "secondaryMuscles": [
      "Trapèzes",
      "Coiffe des rotateurs"
    ],
    "equipment": "Divers",
    "difficulty": 2,
    "isNew": true,
    "description": "Weighted Élévation Frontale. Fiche banque « Épaules » — équipement : Divers. Cible principale : Deltoïdes antérieurs. Muscles secondaires : Trapèzes, Coiffe des rotateurs. Charges légères prioritaires. Épaules basses, pas d’élan du buste ni des trapèzes pour “voler” la série. Monte jusqu’à l’horizontale (ou un peu au-dessus si la technique reste propre), marque une courte pause, redescends sans balancier. Ce n’est pas un shrug : les trapèzes ne doivent pas avaler le mouvement. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
    "variations": [
      "weighted front raise",
      "Weighted Front Raise"
    ]
  },
  "weighted à genoux step with swing": {
    "name": "Weighted à Genoux Step With Swing",
    "category": "Épaules",
    "primaryMuscles": [
      "Deltoïdes"
    ],
    "secondaryMuscles": [
      "Trapèzes",
      "Coiffe des rotateurs"
    ],
    "equipment": "Divers",
    "difficulty": 2,
    "isNew": true,
    "description": "Weighted à Genoux Step With Swing. Fiche banque « Épaules » — équipement : Divers. Cible principale : Deltoïdes. Muscles secondaires : Trapèzes, Coiffe des rotateurs. Pieds ancrés, genoux dans l’axe des pointes. Buste gainé, descente contrôlée jusqu’à l’amplitude propre. Descends en gardant les talons au sol, remonte en poussant le sol, hanches et genoux synchronisés. Reste sur cette variante précise — ne la confonds pas avec un mouvement voisin de la même famille épaules. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
    "variations": [
      "weighted kneeling step with swing",
      "Weighted Kneeling Step With Swing"
    ]
  },
