    "description": "Upward Facing Dog. Fiche banque « Dorsaux » — équipement : Divers. Cible principale : Grand dorsal, Trapèzes. Muscles secondaires : Biceps, Deltoïdes postérieurs. Position de départ stable avec Divers. Contrôle chaque phase du mouvement. Exécute le pattern du GIF fidèlement : même amplitude, même tempo, sans à-coups. Reste sur cette variante précise — ne la confonds pas avec un mouvement voisin de la même famille dorsaux. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
