    "description": "Assisté Triceps Dip à Genoux. Fiche banque « Triceps » — équipement : Poids du corps. Cible principale : Triceps brachial. Muscles secondaires : Deltoïdes antérieurs. Installe-toi de façon stable avec Poids du corps. Omoplates calées, poignets neutres, pieds ancrés. Pousse jusqu’à l’extension presque complète sans verrouiller d’un coup, puis redescends en contrôlant 2–3 secondes. Ce n’est pas un écarté : la trajectoire reste un press, coudes sous la charge. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
