    "description": "Haltères Debout Kickback. Fiche banque « Triceps » — équipement : Haltères. Cible principale : Triceps brachial. Muscles secondaires : Deltoïdes antérieurs. Coudes fixes dans l’espace, avant-bras seuls en mouvement. Épaules basses, tronc gainé. Tends les coudes sans claquer l’articulation. Garde les bras hauts (ou la position de départ) stables pendant toute la série. Reste sur cette variante précise — ne la confonds pas avec un mouvement voisin de la même famille triceps. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
