    "description": "Élastique Unilatéral Twisting Assis Rowing. Fiche banque « Dorsaux » — équipement : Élastique. Cible principale : Grand dorsal, Rhomboïdes. Muscles secondaires : Biceps, Deltoïdes postérieurs. Bassin neutre, côtes rentrées. Pas de traction cervicale : le regard suit le mouvement du tronc. Travail unilatéral : termine un côté (ou alterne proprement) en gardant le bassin et les épaules de niveau — pas de rotation parasite pour aider. Contracte d’abord le transverse, exécute le geste sans arching lombaire ni élan des jambes sauf si la variante le demande explicitement. Ce n’est pas un élan de hanches pour “compter” des reps vides. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
