    "description": "Lever Unilatéral Bent Over Rowing. Fiche banque « Dorsaux » — équipement : Divers. Cible principale : Grand dorsal, Rhomboïdes. Muscles secondaires : Biceps, Deltoïdes postérieurs. Prise solide sur Divers, buste stable, regard neutre. Initie le tirage par les omoplates, pas par les bras seuls. Travail unilatéral : termine un côté (ou alterne proprement) en gardant le bassin et les épaules de niveau — pas de rotation parasite pour aider. Amène les coudes vers l’arrière / le bas selon la variante, serre une seconde en haut, reviens sans lâcher les omoplates trop tôt. Ce n’est pas un curl : le dos tire, les bras accompagnent. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
